(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-171":{scenario:{company:"Jadeport Commercial Bank",supervisor:{name:"Trịnh Quốc Bảo",role:{vi:"Giám đốc Chi nhánh",en:"Branch Director"}},ref_code:"CP-7316",title:{vi:"Đúng tài sản. Đúng tỷ lệ. Đúng hạn mức.",en:"Right collateral. Right ratio. Right limit."},brief:{vi:"Khách hàng doanh nghiệp đề nghị hạn mức vay vốn lưu động 9000 triệu đồng, bảo đảm bằng dây chuyền máy móc đã qua sử dụng 3 năm. Khách tự báo giá thị trường 15000 triệu đồng; Phòng Định giá độc lập định giá 12400 triệu đồng. Bản nháp tờ trình CP-7316 áp tỷ lệ cho vay tối đa trên tài sản bảo đảm (LTV) của bất động sản và dùng giá khách báo. Hãy sửa LTV và mức cấp tín dụng tối đa theo tài sản, rồi lập báo cáo có căn cứ.",en:"A corporate client requests a 9000 million VND working capital line secured by a used machinery line that is 3 years old. The client quotes a market value of 15000 million VND; the independent Valuation Unit appraised it at 12400 million VND. Draft proposal CP-7316 applies the real estate loan-to-value (LTV) ratio and the client's quote. Correct the LTV and the maximum collateral-based limit, then write an evidence-based report."},reference_title:{vi:"Chính sách TSBĐ & chứng thư định giá đã duyệt · CP-7316",en:"Approved collateral policy & valuation report · CP-7316"},fields:[{id:"LTV_RATE",label:{vi:"Tỷ lệ LTV áp dụng",en:"Applied LTV ratio"},initial:"70%",expected:"50%",choices:["70%","50%","40%"],reference:"Chính sách tài sản bảo đảm",ref_value:{vi:"LTV tối đa: bất động sản 70%; máy móc thiết bị 50%; hàng tồn kho 40% (mô phỏng)",en:"Max LTV: real estate 70%; machinery and equipment 50%; inventory 40% (training data)"},hint:{vi:"Tỷ lệ LTV đi theo loại tài sản bảo đảm thực tế của khoản vay, không theo loại tài sản khách quen thế chấp.",en:"The LTV follows the actual collateral of this loan, not the type the client usually pledges."}},{id:"MAX_LIMIT",label:{vi:"Mức cấp tín dụng tối đa (triệu đồng)",en:"Maximum credit limit (million VND)"},initial:"10500",expected:"6200",reference:"Chứng thư định giá tài sản bảo đảm",ref_value:{vi:"Giá khách báo 15000; giá Phòng Định giá độc lập 12400 (triệu đồng)",en:"Client quote 15000; independent Valuation Unit value 12400 (million VND)"},hint:{vi:"Chỉ dùng giá trị do bộ phận định giá độc lập xác định, rồi nhân với LTV đúng loại tài sản.",en:"Use only the value set by the independent valuation unit, then apply the correct LTV."}}],sop32:{vi:"Mức cấp tín dụng tối đa theo tài sản = giá trị định giá độc lập x LTV theo loại tài sản; không dùng giá khách hàng tự báo hoặc giá chào bán.",en:"Maximum collateral-based limit = independent appraised value x LTV for the collateral type; never use the client's own quote or asking price."},context:{label:"LOS / CP-7316",metrics:[{label:{vi:"Hạn mức khách đề nghị",en:"Requested line"},value:"9,000,000,000 VND"},{label:{vi:"Giá định giá độc lập",en:"Independent appraisal"},value:"12,400,000,000 VND"},{label:{vi:"LTV trên bản nháp",en:"Draft LTV"},value:"70%"}]},crisis:{vi:"Giám đốc tài chính của khách hàng gọi riêng: “Em cứ lấy giá 15000 triệu cho đủ hạn mức 9000. Xong việc anh gửi em 1% giá trị khoản vay. Ngân hàng bên cạnh sẵn sàng làm ngay nếu em chậm.”",en:"The client's CFO calls you privately: “Just use the 15000 million value so the 9000 line fits. Once it is approved I will give you 1% of the loan. The bank next door will do it right away if you are slow.”"},options:{safe:{vi:"Từ chối lợi ích cá nhân, dùng giá định giá độc lập và mức 6200 triệu, báo Giám đốc chi nhánh và Tuân thủ; đề xuất khách bổ sung tài sản bảo đảm hoặc giảm hạn mức.",en:"Decline the personal benefit, use the independent value and the 6200 million limit, report to the branch director and Compliance; propose extra collateral or a smaller line."},shortcut:{vi:"Dùng giá khách báo để giữ khách và coi khoản 1% là phí chăm sóc khách hàng.",en:"Use the client's quote to keep the client and treat the 1% as a relationship fee."},wait:{vi:"Không trả lời khách, để hồ sơ nằm đó đến khi khách tự rút.",en:"Do not reply and let the file sit until the client walks away."}},questions:{vi:["Vì sao mức cấp tín dụng tối đa là 6200 triệu chứ không phải 10500 triệu? Hãy dẫn chứng thư định giá và chính sách LTV.","Bạn xử lý đề nghị 1% của khách thế nào theo quy định về quà tặng, xung đột lợi ích và phòng chống tham nhũng?"],en:["Why is the maximum limit 6200 million rather than 10500 million? Cite the valuation report and the LTV policy.","How do you handle the client's 1% offer under the gifts, conflict of interest and anti-corruption rules?"]},hints:{vi:["Xác định loại tài sản bảo đảm thực tế rồi tra bảng LTV trong chính sách.","Lấy đúng giá trị định giá độc lập trước khi nhân với LTV ở SOP mục 3.2.","Đọc SOP mục 4.2: mọi đề nghị lợi ích cá nhân từ khách hàng phải từ chối và báo cáo bằng văn bản."],en:["Identify the actual collateral type, then look up the LTV table in the policy.","Take the independent appraised value before applying the LTV in SOP 3.2.","Re-read SOP 4.2: any personal benefit offered by a client must be refused and reported in writing."]}},learning:{summary:{vi:"Chuyên viên quan hệ khách hàng (RM) phát triển và chăm sóc danh mục khách hàng cá nhân, doanh nghiệp: tìm hiểu nhu cầu, tư vấn sản phẩm tín dụng, tiền gửi, thanh toán, lập tờ trình cấp tín dụng sơ bộ và theo dõi khách hàng sau giải ngân. RM tạo doanh thu bền vững cho ngân hàng khi cân bằng được chỉ tiêu kinh doanh với khẩu vị rủi ro, tuân thủ KYC và đạo đức nghề nghiệp.",en:"A relationship manager (RM) grows and serves a portfolio of retail or corporate clients: understanding needs, advising on credit, deposit and payment products, preparing preliminary credit proposals and monitoring clients after disbursement. An RM builds sustainable revenue by balancing sales targets with risk appetite, KYC compliance and professional ethics."},responsibilities:{vi:["Tìm kiếm, tiếp cận và phát triển khách hàng mới theo phân khúc được giao.","Tìm hiểu nhu cầu, tư vấn gói sản phẩm tín dụng, tiền gửi, thanh toán phù hợp.","Thu thập hồ sơ, thực hiện KYC và lập tờ trình cấp tín dụng sơ bộ.","Phối hợp thẩm định, định giá, phê duyệt và giải ngân đúng điều kiện.","Theo dõi khách hàng sau giải ngân, nhắc nợ và phát hiện sớm dấu hiệu rủi ro."],en:["Prospect, approach and grow new clients in the assigned segment.","Understand needs and advise on suitable credit, deposit and payment packages.","Collect documents, perform KYC and prepare preliminary credit proposals.","Coordinate underwriting, valuation, approval and compliant disbursement.","Monitor clients after disbursement, follow up repayments and spot early risk signals."]},competencies:[{name:{vi:"Tư vấn giải pháp",en:"Solution advisory"},desc:{vi:"Đặt câu hỏi đúng, hiểu dòng tiền khách hàng và đề xuất sản phẩm phù hợp thay vì bán ép.",en:"Ask the right questions, understand client cash flows and propose fitting products instead of pushing."}},{name:{vi:"Phân tích tín dụng cơ bản",en:"Basic credit analysis"},desc:{vi:"Đọc báo cáo tài chính, đánh giá nguồn trả nợ và tài sản bảo đảm trước khi trình.",en:"Read financial statements and assess repayment sources and collateral before proposing."}},{name:{vi:"Đàm phán & giữ chân",en:"Negotiation & retention"},desc:{vi:"Đàm phán lãi suất, phí trong khung phê duyệt và giữ khách bằng chất lượng dịch vụ.",en:"Negotiate rates and fees within approved bands and retain clients through service quality."}},{name:{vi:"Tuân thủ & liêm chính",en:"Compliance & integrity"},desc:{vi:"Thực hiện KYC đầy đủ, từ chối quà tặng, lợi ích vi phạm quy định và báo cáo xung đột lợi ích.",en:"Complete KYC, refuse improper gifts or benefits and report conflicts of interest."}},{name:{vi:"Quản lý danh mục",en:"Portfolio management"},desc:{vi:"Theo dõi dư nợ, huy động, thu nhập và chất lượng nợ của từng khách hàng.",en:"Track loans, deposits, revenue and asset quality for each client."}}],knowledge:{vi:["Luật Các tổ chức tín dụng số 32/2024/QH15 và quy định của NHNN về hoạt động cho vay.","Bộ luật Dân sự 2015 và Nghị định 21/2021/NĐ-CP về bảo đảm thực hiện nghĩa vụ.","Phân tích báo cáo tài chính doanh nghiệp: thanh khoản, đòn bẩy, khả năng trả nợ, dòng tiền.","Nhận biết khách hàng và chủ sở hữu hưởng lợi theo Luật Phòng, chống rửa tiền 2022.","Chuẩn mực tư vấn bán hàng: phù hợp nhu cầu, minh bạch phí, không gắn sản phẩm không bắt buộc với khoản vay."],en:["The Law on Credit Institutions No. 32/2024/QH15 and State Bank rules on lending.","The 2015 Civil Code and Decree 21/2021/ND-CP on securing obligations.","Corporate financial statement analysis: liquidity, leverage, debt service capacity and cash flow.","Customer and beneficial owner identification under the 2022 Anti-Money Laundering Law.","Sales advisory standards: needs-based, transparent fees and no tying of optional products to loans."]},tools:["Bank CRM","Loan Origination System (LOS)","Core Banking","CIC credit report","Pricing & RAROC calculator","Digital onboarding (eKYC)"],tools_en:["Bank CRM","Loan Origination System (LOS)","Core Banking","CIC credit report","Pricing & RAROC calculator","Digital onboarding (eKYC)"],kpis:{vi:["Tăng trưởng dư nợ và huy động ròng của danh mục khách hàng.","Thu nhập thuần từ khách hàng, gồm lãi và phí dịch vụ.","Tỷ lệ nợ quá hạn của danh mục phụ trách.","Tỷ lệ hồ sơ KYC đầy đủ, không bị Tuân thủ trả lại."],en:["Loan and net deposit growth of the client portfolio.","Net revenue per client, including interest and fees.","Past-due ratio of the managed portfolio.","Share of complete KYC files not returned by Compliance."]},day:[{time:"08:00",vi:"Xem báo cáo dư nợ, khoản đến hạn và cảnh báo quá hạn của danh mục.",en:"Review loan balances, upcoming maturities and past-due alerts for the portfolio."},{time:"09:30",vi:"Thăm nhà máy khách hàng, khảo sát tài sản bảo đảm và nhu cầu vốn.",en:"Visit a client's plant to inspect collateral and discuss funding needs."},{time:"13:30",vi:"Hoàn thiện tờ trình tín dụng, gửi Phòng Định giá và Thẩm định.",en:"Finalise the credit proposal and send it to Valuation and Underwriting."},{time:"15:30",vi:"Gọi điện chăm sóc khách hàng, giới thiệu dịch vụ thanh toán phù hợp.",en:"Call clients and introduce suitable payment services."},{time:"17:00",vi:"Cập nhật CRM, ghi nhận cơ hội và rủi ro mới phát hiện.",en:"Update the CRM with new opportunities and risks spotted."}],mistakes:{vi:["Dùng giá khách tự báo thay vì giá định giá độc lập để tính hạn mức.","Áp LTV của bất động sản cho máy móc, hàng tồn kho có rủi ro giảm giá cao hơn.","Nhận quà, hoa hồng từ khách hoặc ép khách mua sản phẩm kèm để đạt chỉ tiêu."],en:["Using the client's own quote instead of the independent appraisal to size the limit.","Applying the real estate LTV to machinery or inventory that lose value faster.","Taking gifts or commissions from clients or forcing add-on products to hit targets."]},career:[{vi:"Chuyên viên hỗ trợ quan hệ khách hàng",en:"Relationship support officer"},{vi:"Chuyên viên quan hệ khách hàng (RM)",en:"Relationship manager (RM)"},{vi:"Trưởng phòng Khách hàng doanh nghiệp / cá nhân",en:"Head of corporate or retail banking"},{vi:"Giám đốc Chi nhánh",en:"Branch director"}],glossary:[{term:"RM",vi:"Chuyên viên quan hệ khách hàng, đầu mối phục vụ và phát triển một danh mục khách hàng.",en:"Relationship manager, the single point of contact who serves and grows a client portfolio."},{term:"LTV",vi:"Tỷ lệ dư nợ tối đa trên giá trị tài sản bảo đảm, khác nhau theo loại tài sản.",en:"Loan-to-value: maximum loan as a share of collateral value, set by collateral type."},{term:"KYC",vi:"Nhận biết khách hàng: xác minh danh tính, chủ sở hữu hưởng lợi, ngành nghề và nguồn tiền.",en:"Know your customer: verifying identity, beneficial owners, business and source of funds."},{term:"RAROC",vi:"Lợi nhuận điều chỉnh theo rủi ro trên vốn, dùng để định giá khoản vay.",en:"Risk-adjusted return on capital, used to price loans."},{term:"Cross-sell",vi:"Bán chéo sản phẩm phù hợp nhu cầu cho khách hàng hiện hữu, trên cơ sở tự nguyện.",en:"Selling additional suitable products to existing clients on a voluntary basis."}],quiz:[{q:{vi:"Tài sản bảo đảm là hàng tồn kho định giá 5000 triệu, LTV hàng tồn kho 40%. Mức cấp tín dụng tối đa theo tài sản là bao nhiêu?",en:"Collateral is inventory appraised at 5000 million with a 40% inventory LTV. What is the maximum collateral-based limit?"},options:{vi:["5000 triệu","3500 triệu","2000 triệu","2500 triệu"],en:["5000 million","3500 million","2000 million","2500 million"]},answer:2,explain:{vi:"Mức tối đa = 5000 x 40% = 2000 triệu đồng.",en:"Maximum = 5000 x 40% = 2000 million."}},{q:{vi:"Căn cứ giá trị tài sản bảo đảm khi lập tờ trình là gì?",en:"Which collateral value should a credit proposal use?"},options:{vi:["Giá khách hàng tự báo","Giá trị do bộ phận định giá độc lập hoặc tổ chức thẩm định giá được chấp thuận xác định","Giá mua ban đầu trên hóa đơn","Giá cao nhất tìm được trên mạng"],en:["The client's own quote","The value set by the independent valuation unit or an approved appraiser","The original purchase invoice price","The highest price found online"]},answer:1,explain:{vi:"Giá trị tài sản phải được định giá độc lập để tránh xung đột lợi ích và đánh giá quá cao.",en:"Collateral must be valued independently to avoid conflicts of interest and overvaluation."}},{q:{vi:"Chi nhánh yêu cầu RM buộc khách mua bảo hiểm nhân thọ mới được giải ngân khoản vay. Cách làm đúng là gì?",en:"The branch tells RMs to make life insurance a condition of loan disbursement. What is right?"},options:{vi:["Chỉ giới thiệu, để khách tự nguyện, không gắn với điều kiện giải ngân và báo cáo nếu bị ép","Làm theo vì là chỉ tiêu","Giải ngân trước rồi tự trừ phí bảo hiểm","Ký hộ khách hợp đồng bảo hiểm"],en:["Only introduce it, keep it voluntary, never tie it to disbursement and report the pressure","Comply because it is a target","Disburse first and deduct the premium","Sign the policy on the client's behalf"]},answer:0,explain:{vi:"Quy định hiện hành cấm gắn việc mua bảo hiểm không bắt buộc với việc cung cấp dịch vụ ngân hàng.",en:"Current rules prohibit tying optional insurance to the provision of banking services."}},{q:{vi:"Khi KYC khách hàng doanh nghiệp, RM bắt buộc phải xác định ai?",en:"In corporate KYC, whom must the RM identify?"},options:{vi:["Chỉ kế toán trưởng","Chỉ người đến giao dịch","Đối tác lớn nhất của khách","Người đại diện theo pháp luật và chủ sở hữu hưởng lợi"],en:["Only the chief accountant","Only the person at the counter","The client's largest partner","The legal representative and the beneficial owners"]},answer:3,explain:{vi:"Pháp luật phòng chống rửa tiền yêu cầu xác định người đại diện và cá nhân thực sự sở hữu, kiểm soát doanh nghiệp.",en:"AML law requires identifying the representative and the individuals who truly own or control the company."}}]}}})})(window.KKR);
